// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, uint256 t2, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        t = bound(t, 1, type(uint256).max - 1);
        t2 = bound(t2, 0, t); // re-call at or before the same timestamp

        vm.deal(actor, 20 ether);

        // first call at time t
        vm.warp(t);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call at time t2 <= t: correct contract stores t+1, so
        // require(block.timestamp > pastBlockTime) must fail
        vm.warp(t2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertFalse(ok2);
    }
}
